#include <iostream>
#include <vector>

void countingSort(std::vector<int>& arr) {
    if (arr.empty()) return;

    // 1. Find the maximum element to determine range
    int maxVal = arr[0];
    for (int val : arr) {
        if (val > maxVal) maxVal = val;
    }

    // 2. Create count array filled with zeros
    std::vector<int> count(maxVal + 1, 0);

    // 3. Count frequencies
    for (int val : arr) {
        count[val]++;
    }

    // 4. Modify count to store cumulative indices
    for (int i = 1; i <= maxVal; i++) {
        count[i] += count[i - 1];
    }

    // 5. Build output array
    std::vector<int> output(arr.size());
    for (int i = arr.size() - 1; i >= 0; i--) {
        output[count[arr[i]] - 1] = arr[i];
        count[arr[i]]--;
    }

    // 6. Copy back to original array
    arr = output;
}
